const host = "192.168.178.192";
const calls = [
    ["Shelly.GetStatus", {}],
    ["Shelly.GetConfig", {}],
    ["Shelly.GetComponents", {offset: 0, include: ["config", "status"]}],
    ["Shelly.ListMethods", {}],
    ["Script.List", {}]
];

return [calls.map((call, index) => ({
    url: `http://${host}/rpc`,
    method: "POST",
    headers: {"content-type": "application/json"},
    payload: JSON.stringify({
        id: 1000 + index,
        src: "nod34-shb-test",
        method: call[0],
        params: call[1]
    }),
    rpcMethod: call[0],
    testPhase: "read-only"
}))];

const host = "192.168.178.192";
msg.url = `http://${host}/rpc`;
msg.method = "POST";
msg.headers = {"content-type": "application/json"};
msg.payload = JSON.stringify({
    id: 2000,
    src: "nod34-shb-test",
    method: "Script.List",
    params: {}
});
msg.shellyHost = host;
return msg;

const body = msg.payload || {};
const result = body.result || body;
const scripts = Array.isArray(result.scripts) ? result.scripts : (Array.isArray(result) ? result : []);
const script = scripts.find(item => item && item.name === "SmartHomeBoard BLE v1");

if (!script) {
    node.error("Script 'SmartHomeBoard BLE v1' wurde auf diesem Shelly nicht gefunden", msg);
    return null;
}

const host = msg.shellyHost || "192.168.178.192";
const scriptId = Number(script.id);
return {
    url: `http://${host}/rpc`,
    method: "POST",
    headers: {"content-type": "application/json"},
    payload: JSON.stringify({
        id: 2050,
        src: "nod34-shb-test",
        method: "Script.GetCode",
        params: {id: scriptId}
    }),
    shellyHost: host,
    scriptId,
    rpcMethod: "Script.GetCode",
    testPhase: "read-script-code"
};

const body = msg.payload || {};
const result = body.result || body;
const code = result.data;
const left = Number(result.left || 0);

if (typeof code !== "string" || code.length === 0) {
    node.error("Script.GetCode hat keinen Script-Code geliefert – Test abgebrochen", msg);
    return null;
}
if (left > 0) {
    node.error(`Script.GetCode ist unvollständig (${left} Bytes fehlen) – Test abgebrochen`, msg);
    return null;
}

const host = msg.shellyHost || "192.168.178.192";
const scriptId = Number(msg.scriptId);
const calls = [
    [0, "Script.Stop", {id: scriptId}],
    [2500, "Script.PutCode", {id: scriptId, code, append: false}],
    [5000, "Script.SetConfig", {id: scriptId, config: {enable: true}}],
    [7500, "Script.GetStatus", {id: scriptId}],
    [10000, "Script.Start", {id: scriptId}]
];

calls.forEach(([delay, method, params], index) => {
    setTimeout(() => node.send({
        url: `http://${host}/rpc`,
        method: "POST",
        headers: {"content-type": "application/json"},
        payload: JSON.stringify({
            id: 2100 + index,
            src: "nod34-shb-test",
            method,
            params
        }),
        rpcMethod: method,
        scriptId,
        testPhase: "script-rewrite"
    }), delay);
});

node.status({fill: "yellow", shape: "dot", text: `Script ${scriptId}: Stop/PutCode/Config/Status/Start`});
setTimeout(() => node.status({}), 13000);
return null;
